-- 016_signatory_signature.sql
-- Stores Abu-Baker Nsubuga's signature & company stamp (transparent PNG) on his
-- approved-signatory entry, so it prints above his line wherever he signs:
-- statements, purchase orders, payment vouchers, reports and Excel exports.
-- Replace or remove it from Settings -> General -> Approved signatories.
-- Only fills it in when no signature has been uploaded yet.
UPDATE settings
SET value = jsonb_set(
      value,
      '{signatories}',
      (
        SELECT jsonb_agg(
          CASE
            WHEN s->>'name' ILIKE '%nsubuga%' AND COALESCE(s->>'signature', '') = ''
              THEN jsonb_set(s, '{signature}', to_jsonb('data:image/png;base64,'::text), true)
            ELSE s
          END
        )
        FROM jsonb_array_elements(value->'signatories') AS s
      ),
      true
    ),
    updated_at = now()
WHERE key = 'app'
  AND jsonb_typeof(value->'signatories') = 'array'
  AND jsonb_array_length(value->'signatories') > 0;
